const originalTextNodes = new WeakMap<Text, string>()
function Progress({ value, className = "" }: { value: number; className?: string }) { return <div className={`h-2 overflow-hidden rounded-full bg-[#e5e5e5] ${className}`}><div className="h-full rounded-full bg-[#fca311] transition-all" style={{ width: `${value}%` }} /></div> }
function AppShell({ screen, setScreen, children, language, setLanguage }: any) { const title = screens.find((item) => item.id === screen)?.label; const isLanding = ["cover", "concept", "access"].includes(screen);
  useEffect(() => {
    const translatePage = () => {
      const dictionary = { ...(fallbackTranslations[language] ?? {}), ...(translatedText[language] ?? {}), ...(siteTranslations[language] ?? {}), ...(commonTranslations[language] ?? {}) }
      const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT)
      const nodes: Text[] = []
      let node: Node | null
      while ((node = walker.nextNode())) nodes.push(node as Text)
      nodes.forEach((textNode) => {
        const parent = textNode.parentElement
        if (!parent || ["SCRIPT", "STYLE", "SELECT", "OPTION", "SVG"].includes(parent.tagName)) return
        const original = originalTextNodes.get(textNode) ?? textNode.nodeValue ?? ""
        originalTextNodes.set(textNode, original)
        const trimmed = original.trim()
        const translated = dictionary[trimmed]
        let nextValue = translated ? original.replace(trimmed, translated) : original
        if (!translated && language !== "PT-BR" && Object.keys(dictionary).length) {
          const matches = Object.keys(dictionary).filter((key) => key.length > 2 && original.includes(key)).sort((a, b) => b.length - a.length)
          for (const key of matches) nextValue = nextValue.split(key).join(dictionary[key])
        }
        if (textNode.nodeValue !== nextValue) textNode.nodeValue = nextValue
      })
    }
    translatePage()
    const observer = new MutationObserver(translatePage)
    observer.observe(document.body, { childList: true, subtree: true })
    return () => observer.disconnect()
  }, [language])
  return <div className="min-h-screen bg-[#f7f8fa] text-black"><header className="sticky top-0 z-20 border-b border-[#e5e5e5] bg-white/95 backdrop-blur"><div className="mx-auto flex h-16 max-w-6xl items-center justify-between px-4 sm:px-6"><button onClick={() => setScreen("dashboard")} className="flex items-center gap-2 font-black tracking-tight"><span className="grid size-9 place-items-center rounded-xl bg-[#101827] text-[#fca311]"><Plane size={19} /></span>DOMINE <span className="text-[#298edd]">SUAS MILHAS</span></button><div className="flex items-center gap-3"><Globe2 size={17} className="text-[#298edd]" /><select aria-label="Idioma" value={language} onChange={(e) => setLanguage(e.target.value)} className="bg-transparent text-sm font-bold outline-none">{languages.map((item) => <option key={item}>{item}</option>)}</select><button className="hidden rounded-full border border-[#e5e5e5] p-2 sm:block" aria-label="Abrir menu"><Menu size={18} /></button></div></div></header><main className="mx-auto max-w-6xl px-4 pb-28 pt-7 sm:px-6">{!isLanding && <div className="mb-6"><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#298edd]">{translations[language].journey} · {title}</p><h1 className="mt-1 text-2xl font-black tracking-tight sm:text-3xl">{title}</h1></div>}{children}</main><footer className="border-t border-[#e5e5e5] bg-[#101827] px-4 py-10 text-white"><div className="mx-auto grid max-w-6xl gap-8 sm:grid-cols-[1.4fr_1fr_1fr]"><div><p className="font-black tracking-tight">DOMINE <span className="text-[#298edd]">SUAS MILHAS</span></p><p className="mt-3 max-w-xs text-sm leading-6 text-slate-400">{translations[language].copyright}</p></div><div><p className="text-xs font-black uppercase tracking-widest text-[#fca311]">Navegação</p><div className="mt-3 flex flex-col items-start gap-2 text-sm text-slate-300"><button onClick={() => setScreen("course")} className="hover:text-white">{translations[language].footerCourse}</button><button onClick={() => setScreen("tools")} className="hover:text-white">{translations[language].footerTools}</button><button onClick={() => setScreen("materials")} className="hover:text-white">{translations[language].footerMaterials}</button></div></div><div><p className="text-xs font-black uppercase tracking-widest text-[#fca311]">Ajuda</p><div className="mt-3 flex flex-col items-start gap-2 text-sm text-slate-300"><button onClick={() => setScreen("faq")} className="hover:text-white">{translations[language].footerFaq}</button><button onClick={() => setScreen("faq")} className="hover:text-white">{translations[language].footerSupport}</button></div></div></div></footer><nav className="fixed bottom-0 left-0 right-0 z-30 border-t border-[#e5e5e5] bg-white shadow-[0_-8px_30px_rgba(16,24,39,.08)]"><div className="mx-auto flex max-w-xl justify-around px-2 py-2">{navItems.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setScreen(id)} className={`flex min-h-12 min-w-16 flex-col items-center justify-center gap-1 rounded-xl text-[10px] font-bold transition ${screen === id ? "text-[#fca311]" : "text-slate-500"}`}><Icon size={20} /><span>{translations[language][id] ?? label}</span></button>)}</div></nav></div> }
function Cover({ setScreen }: any) { return <section className="grid min-h-[calc(100vh-9rem)] items-center gap-10 py-10 lg:grid-cols-[1.1fr_.9fr]"><div><div className="mb-5 inline-flex items-center gap-2 rounded-full bg-[#fff2d8] px-3 py-2 text-xs font-black text-[#9a5a00]"><Zap size={14} /> MÉTODO PRÁTICO E SEGURO</div><h1 className="max-w-2xl text-5xl font-black leading-[.98] tracking-[-.06em] sm:text-7xl">DOMINE<br /><span className="text-[#298edd]">SUAS MILHAS.</span></h1><p className="mt-6 max-w-lg text-lg leading-8 text-slate-600">Aprenda a acumular, multiplicar e utilizar seus pontos de forma estratégica — sem gastar mais e sem cair em promessas fáceis.</p><div className="mt-8 flex flex-wrap gap-3"><button onClick={() => setScreen("concept")} className="rounded-xl bg-[#101827] px-6 py-4 font-black text-white shadow-lg shadow-slate-300 transition hover:-translate-y-0.5">COMEÇAR JORNADA <ChevronRight className="ml-2 inline" size={18} /></button><button onClick={() => setScreen("concept")} className="rounded-xl border border-[#e5e5e5] bg-white px-6 py-4 font-bold">Como funciona</button></div><p className="mt-5 text-xs text-slate-500">Aprenda no seu ritmo · Acesso demonstrativo do MVP</p></div><div className="relative mx-auto w-full max-w-md"><div className="absolute -inset-5 rounded-[2.5rem] bg-[#298edd]/10 blur-2xl" /><div className="relative rounded-[2rem] bg-[#101827] p-6 text-white shadow-2xl"><div className="flex items-center justify-between"><span className="text-sm font-bold text-slate-300">Seu próximo destino</span><span className="rounded-full bg-[#fca311] px-2 py-1 text-[10px] font-black text-black">NÍVEL 01</span></div><div className="mt-12 flex items-center gap-4"><div className="grid size-16 place-items-center rounded-2xl bg-[#298edd]"><Plane size={30} /></div><div><p className="text-2xl font-black">Rumo à liberdade</p><p className="text-sm text-slate-400">Sua primeira viagem começa aqui</p></div></div><div className="mt-12 rounded-2xl bg-white/10 p-4"><div className="flex justify-between text-sm"><span>Progresso da jornada</span><b>18%</b></div><Progress value={18} className="mt-3 bg-white/20" /><p className="mt-3 text-xs text-slate-400">3 de 18 aulas concluídas</p></div></div></div></section> }
function Concept({ setScreen }: any) { const pillars = [[BookOpen, "APRENDER", "Entenda o básico sem complicação."], [Calculator, "PRATICAR", "Transforme teoria em decisões."], [Compass, "SIMULAR", "Teste cenários antes de agir."], [Rocket, "EVOLUIR", "Acompanhe seu progresso real."]]; return <section className="py-8"><div className="max-w-2xl"><p className="font-black text-[#fca311]">UM MÉTODO EM QUATRO PASSOS</p><h1 className="mt-3 text-4xl font-black tracking-tight sm:text-6xl">Milhas não são sorte.<br /><span className="text-[#298edd]">São estratégia.</span></h1><p className="mt-5 text-lg leading-8 text-slate-600">Uma jornada guiada para você tomar decisões melhores, economizar no planejamento e viajar com mais consciência.</p></div><div className="mt-12 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{pillars.map(([Icon, title, text], i) => <div key={title as string} className="rounded-2xl border border-[#e5e5e5] bg-white p-5"><span className={`grid size-11 place-items-center rounded-xl ${i % 2 ? "bg-[#dff0ff] text-[#298edd]" : "bg-[#fff2d8] text-[#c37800]"}`}><Icon size={21} /></span><h3 className="mt-7 font-black">{title as string}</h3><p className="mt-2 text-sm leading-6 text-slate-500">{text as string}</p></div>)}</div><button onClick={() => setScreen("access")} className="mt-10 rounded-xl bg-[#298edd] px-6 py-4 font-black text-white">QUERO COMEÇAR <ChevronRight className="ml-2 inline" size={18} /></button></section> }
function Access() {
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState("")

  async function startCheckout() {
    setIsLoading(true)
    setError("")
    try {
      const response = await fetch("/api/create-session", { method: "POST" })
      const data = await response.json()
      if (!response.ok || !data.init_point) throw new Error(data.message)
      window.location.assign(data.init_point)
    } catch {
      setError("Não foi possível abrir o pagamento. Tente novamente em instantes.")
      setIsLoading(false)
    }
  }

  return <div className="grid gap-6 lg:grid-cols-[1fr_380px]">
    <div className="rounded-3xl bg-[#101827] p-7 text-white sm:p-10">
      <p className="text-sm font-bold text-[#fca311]">ACESSO À JORNADA</p>
      <h2 className="mt-3 text-3xl font-black">Domine suas milhas.<br />Viaje com estratégia.</h2>
      <p className="mt-5 max-w-md leading-7 text-slate-300">Curso completo para você entender, acumular e usar milhas aéreas com mais segurança.</p>
      <div className="mt-12 grid gap-4 text-sm text-slate-300 sm:grid-cols-3"><span><Check className="mb-2 text-[#fca311]" />Curso completo</span><span><Check className="mb-2 text-[#fca311]" />Ferramentas práticas</span><span><Check className="mb-2 text-[#fca311]" />Certificado</span></div>
    </div>
    <div className="rounded-3xl border border-[#e5e5e5] bg-white p-6">
      <p className="text-xs font-black uppercase tracking-widest text-slate-500">Curso Domine Milhas</p>
      <p className="mt-4 text-3xl font-black">R$ 49,90</p>
      <p className="mt-1 text-xs text-slate-500">Pagamento único · acesso após confirmação</p>
      <div className="mt-6 grid grid-cols-2 gap-2">
        <div className="rounded-xl border border-[#e5e5e5] p-3 text-sm font-black"><Wallet className="mb-2 text-[#c37800]" size={18} />PIX<p className="text-[10px] font-normal text-slate-500">Conforme disponível</p></div>
        <div className="rounded-xl border border-[#e5e5e5] p-3 text-sm font-black"><CreditCard className="mb-2 text-[#298edd]" size={18} />Cartão<p className="text-[10px] font-normal text-slate-500">Até 12x no checkout</p></div>
      </div>
      <button onClick={startCheckout} disabled={isLoading} className="mt-5 w-full rounded-xl bg-[#fca311] px-4 py-4 font-black text-black disabled:cursor-wait disabled:opacity-70">{isLoading ? "ABRINDO CHECKOUT..." : "COMPRAR AGORA"}</button>
      {error && <p role="alert" className="mt-3 text-center text-xs text-red-600">{error}</p>}
      <p className="mt-4 text-center text-xs text-slate-500">Você será direcionado ao ambiente seguro do Mercado Pago.</p>
    </div>
  </div>
}
function Dashboard({ setScreen }: any) { return <div className="grid gap-5 lg:grid-cols-[1.4fr_.8fr]"><div className="rounded-3xl bg-[#101827] p-7 text-white"><div className="flex items-center justify-between"><div><p className="text-sm text-slate-300">Olá, João.</p><h2 className="mt-1 text-3xl font-black">Sua próxima viagem<br /><span className="text-[#fca311]">começa hoje.</span></h2></div><div className="grid size-14 place-items-center rounded-2xl bg-[#298edd]"><Plane /></div></div><div className="mt-9"><div className="flex justify-between text-sm"><span>Progresso do curso</span><b>18%</b></div><Progress value={18} className="mt-3 bg-white/20" /><p className="mt-3 text-xs text-slate-400">3 de 18 aulas · 240 XP para o próximo nível</p></div></div><div className="rounded-3xl border border-[#e5e5e5] bg-white p-6"><div className="flex items-center gap-3"><span className="grid size-11 place-items-center rounded-xl bg-[#fff2d8] text-[#c37800]"><CirclePlay /></span><div><p className="text-xs font-bold text-slate-500">PRÓXIMA AULA</p><p className="font-black">O que são milhas?</p></div></div><button onClick={() => setScreen("lesson")} className="mt-6 w-full rounded-xl bg-[#298edd] py-3 font-black text-white">CONTINUAR AULA</button></div><div className="grid gap-4 sm:grid-cols-3 lg:col-span-2">{[[Zap,"240","XP acumulados"],[Trophy,"3","Conquistas"],[Target,"01","Missão atual"]].map(([Icon, value, label]) => <div key={label as string} className="rounded-2xl border border-[#e5e5e5] bg-white p-5"><Icon className="text-[#fca311]" size={20}/><p className="mt-5 text-2xl font-black">{value as string}</p><p className="text-sm text-slate-500">{label as string}</p></div>)}</div><div className="rounded-2xl border border-[#e5e5e5] bg-white p-6 lg:col-span-2"><div className="flex items-center justify-between"><h3 className="font-black">Atalhos rápidos</h3><button onClick={() => setScreen("tools")} className="text-sm font-bold text-[#298edd]">Ver ferramentas</button></div><div className="mt-5 grid gap-3 sm:grid-cols-4">{[[Calculator,"Simulador"],[Wallet,"Comparador"],[Target,"Quiz"],[Award,"Missões"]].map(([Icon, label]) => <button onClick={() => setScreen(label === "Quiz" ? "missions" : label === "Comparador" ? "compare" : "tools")} key={label as string} className="flex items-center gap-3 rounded-xl bg-[#f7f8fa] p-3 text-left text-sm font-bold"><Icon size={18} className="text-[#298edd]" />{label as string}</button>)}</div></div></div> }
function Generic({ screen, setScreen, language }: any) { if (screen === "welcome") return <div className="mx-auto max-w-2xl rounded-3xl bg-[#101827] p-8 text-white sm:p-12"><span className="grid size-14 place-items-center rounded-2xl bg-[#fca311] text-black"><Rocket /></span><p className="mt-8 text-sm font-bold text-[#fca311]">PRIMEIRO ACESSO</p><h2 className="mt-2 text-4xl font-black">Olá, João.</h2><p className="mt-4 leading-7 text-slate-300">Você está no nível 1 — Iniciante. Vamos começar com uma missão simples para colocar seu conhecimento em movimento.</p><div className="mt-8 rounded-2xl bg-white/10 p-5"><div className="flex justify-between text-sm"><b>XP do nível 1</b><span>0 / 100</span></div><Progress value={0} className="mt-3 bg-white/20" /></div><button onClick={() => setScreen("course")} className="mt-7 rounded-xl bg-[#fca311] px-6 py-4 font-black text-black">COMEÇAR CURSO</button></div>; if (screen === "course") return <div className="grid gap-4">{["Fundamentos das milhas","Acúmulo inteligente","Resgate e planejamento","Sua primeira viagem"].map((item, i) => <button onClick={() => setScreen("lesson")} key={item} className="flex items-center gap-4 rounded-2xl border border-[#e5e5e5] bg-white p-5 text-left"><span className={`grid size-11 place-items-center rounded-full font-black ${i === 0 ? "bg-[#fca311]" : i === 1 ? "bg-[#dff0ff] text-[#298edd]" : "bg-[#f7f8fa] text-slate-400"}`}>{i < 2 ? <Check size={18} /> : i + 1}</span><span className="flex-1"><b>{item}</b><small className="mt-1 block text-slate-500">{i === 0 ? "3 aulas · concluído" : i === 1 ? "5 aulas · em andamento" : "4 aulas · bloqueado"}</small></span><ChevronRight className="text-slate-400" /></button>)}</div>; if (screen === "lesson") return <div className="grid gap-6 lg:grid-cols-[280px_1fr]"><aside className="rounded-2xl border border-[#e5e5e5] bg-white p-4"><p className="mb-4 text-xs font-black uppercase tracking-widest text-slate-500">Módulo 01</p>{["O que são milhas?","Pontos x milhas","Exercício prático"].map((x,i)=><div key={x} className={`rounded-xl p-3 text-sm font-bold ${i===0?"bg-[#fff2d8]":"text-slate-500"}`}>{x}</div>)}</aside><article className="rounded-3xl border border-[#e5e5e5] bg-white p-7"><div className="grid aspect-video place-items-center rounded-2xl bg-[#101827] text-center text-white"><div><CirclePlay size={50} className="mx-auto text-[#fca311]" /><p className="mt-3 text-sm font-bold">Conteúdo da aula · 08:42</p></div></div><h2 className="mt-7 text-2xl font-black">O que são milhas?</h2><p className="mt-3 leading-7 text-slate-600">Milhas são pontos acumulados em programas de fidelidade. Nesta aula você vai entender como elas funcionam, onde encontrá-las e como planejar seu primeiro resgate.</p><div className="mt-6 flex gap-3"><button onClick={() => setScreen("course")} className="rounded-xl border px-5 py-3 font-bold">Voltar</button><button onClick={() => setScreen("tools")} className="rounded-xl bg-[#298edd] px-5 py-3 font-black text-white">Concluir e próxima</button></div></article></div>; if (screen === "tools" || screen === "compare") return <Tools screen={screen} setScreen={setScreen} language={language} />; if (screen === "missions") return <Missions />; if (screen === "profile") return <Profile setScreen={setScreen} />; if (["achievements", "project", "materials", "faq"].includes(screen)) return <InfoScreen screen={screen} />; return <Dashboard setScreen={setScreen} /> }
function Tools({ screen, setScreen, language = "PT-BR" }: any) { const [spend, setSpend] = useState(3000); const miles = useMemo(() => Math.round(spend * 2.2), [spend]); const currency = ({ "PT-BR": { code: "BRL", locale: "pt-BR" }, "PT-PT": { code: "EUR", locale: "pt-PT" }, EN: { code: "USD", locale: "en-US" }, ES: { code: "EUR", locale: "es-ES" }, JA: { code: "JPY", locale: "ja-JP" }, ZH: { code: "CNY", locale: "zh-CN" } } as const)[language as keyof typeof currency] ?? { code: "BRL", locale: "pt-BR" }; const money = (value: number) => new Intl.NumberFormat(currency.locale, { style: "currency", currency: currency.code, maximumFractionDigits: currency.code === "JPY" ? 0 : 2 }).format(value); return <div className="grid gap-5 lg:grid-cols-2"><div className="rounded-3xl border border-[#e5e5e5] bg-white p-7"><span className="grid size-11 place-items-center rounded-xl bg-[#dff0ff] text-[#298edd]"><Calculator /></span><h2 className="mt-5 text-2xl font-black">Simulador de acúmulo</h2><p className="mt-2 text-sm leading-6 text-slate-500">Exemplo didático com valores fictícios. Veja como seus gastos podem virar pontos.</p><label className="mt-7 block text-sm font-bold">Gasto mensal estimado</label><input type="range" min="500" max="10000" step="100" value={spend} onChange={(e) => setSpend(Number(e.target.value))} className="mt-5 w-full accent-[#298edd]" /><div className="mt-4 flex justify-between"><b>{money(spend)}</b><span className="font-black text-[#298edd]">{miles.toLocaleString(currency.locale)} pontos</span></div><button onClick={() => setScreen("compare")} className="mt-7 rounded-xl bg-[#101827] px-5 py-3 font-black text-white">Comparar resgate</button></div><div className="rounded-3xl bg-[#fff8e9] p-7"><p className="text-xs font-black uppercase tracking-widest text-[#9a5a00]">Calculadora de milheiro</p><h2 className="mt-3 text-2xl font-black">Qual é o valor real?</h2><div className="mt-8 rounded-2xl bg-white p-5"><div className="flex justify-between"><span>Valor pago</span><b>{money(450)}</b></div><div className="mt-4 flex justify-between"><span>Milhas recebidas</span><b>{(30000).toLocaleString(currency.locale)}</b></div><div className="my-5 border-t border-dashed border-[#e5e5e5]" /><div className="flex justify-between"><span className="font-bold">Custo por milheiro</span><b className="text-xl text-[#c37800]">{money(15)}</b></div></div><p className="mt-5 text-xs leading-5 text-slate-600">Milhas são ferramenta de planejamento e economia, não dinheiro fácil.</p></div></div> }
function Missions() { const [selected, setSelected] = useState<string | null>(null); return <div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="rounded-3xl bg-[#101827] p-7 text-white"><div className="flex justify-between"><div><p className="text-sm font-bold text-[#fca311]">MISSÃO ATUAL · +100 XP</p><h2 className="mt-3 text-3xl font-black">Identifique o melhor caminho</h2></div><Target className="text-[#fca311]" /></div><p className="mt-6 leading-7 text-slate-300">Qual atitude é mais estratégica para começar a acumular milhas?</p><div className="mt-6 grid gap-3">{["Gastar mais para ganhar mais pontos", "Entender seus hábitos e escolher um programa adequado", "Comprar qualquer promoção que aparecer"].map((x) => <button key={x} onClick={() => setSelected(x)} className={`rounded-xl border p-4 text-left text-sm font-bold transition ${selected === x ? x.startsWith("Entender") ? "border-[#80d38d] bg-[#19452a]" : "border-red-300 bg-red-950" : "border-white/15 bg-white/5 hover:bg-white/10"}`}>{x}{selected === x && <Check className="float-right" size={18} />}</button>)}</div>{selected && <p className="mt-5 rounded-xl bg-white/10 p-4 text-sm text-slate-200">{selected.startsWith("Entender") ? "Resposta correta. A estratégia começa pelo seu comportamento, não por gastar mais." : "Quase. Lembre-se: milhas não justificam gastos desnecessários."}</p>}</div><div className="rounded-3xl border border-[#e5e5e5] bg-white p-7"><p className="text-xs font-black uppercase tracking-widest text-slate-500">Sua sequência</p><h3 className="mt-2 text-2xl font-black">3 dias ativos</h3><Progress value={60} className="mt-5" />{["Aula 01 concluída","Calculadora utilizada","Quiz respondido","Projeto final"].map((x,i)=><div key={x} className="mt-5 flex items-center gap-3 text-sm"><span className={`grid size-8 place-items-center rounded-full ${i<2?"bg-[#fca311]":"bg-[#f7f8fa] text-slate-400"}`}>{i<2?<Check size={15}/>:<Lock size={14}/>}</span><span className={i<2?"font-bold":"text-slate-400"}>{x}</span></div>)}</div></div> }
function Profile({ setScreen }: any) { return <div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="rounded-3xl bg-[#101827] p-7 text-white"><div className="grid size-16 place-items-center rounded-full bg-[#fca311] text-2xl font-black text-black">JO</div><h2 className="mt-5 text-2xl font-black">João Oliveira</h2><p className="text-sm text-slate-400">joao@email.com</p><div className="mt-8 flex justify-between text-sm"><span>Nível 1 · Iniciante</span><b className="text-[#fca311]">240 XP</b></div><Progress value={42} className="mt-3 bg-white/20" /><button onClick={() => setScreen("achievements")} className="mt-7 w-full rounded-xl bg-white/10 py-3 font-bold">Ver conquistas</button></div><div className="rounded-3xl border border-[#e5e5e5] bg-white p-7"><div className="flex items-center gap-3"><Globe2 className="text-[#298edd]"/><div><h2 className="text-xl font-black">Idioma da plataforma</h2><p className="text-sm text-slate-500">Altere quando quiser.</p></div></div><div className="mt-7 grid gap-2 sm:grid-cols-2">{languages.map((lang,i)=><button key={lang} className={`flex items-center justify-between rounded-xl border p-4 text-left font-bold ${i===0?"border-[#fca311] bg-[#fff8e9]":"border-[#e5e5e5]"}`}>{lang}<span className="text-sm text-slate-400">{i===0?<Check size={17}/>:""}</span></button>)}</div></div></div> }
function InfoScreen({ screen }: any) { const content: any = { achievements:["Conquistas e níveis","Você está construindo consistência. Cada passo conta.",["Primeiros passos","Calculadora curiosa","Aluno estratégico","Planejador de viagens"]], project:["Minha primeira viagem com milhas","Um projeto guiado em 6 etapas para transformar conhecimento em planejamento.",["Definir destino","Escolher datas","Pesquisar programas","Comparar dinheiro e milhas","Montar estratégia","Celebrar o resultado"]], materials:["Materiais e certificado","Tudo o que você precisa para continuar praticando.",["Checklist: primeira viagem","Planilha de custo por milheiro","Guia de programas","Certificado: disponível após conclusão"]], faq:["Perguntas frequentes","Respostas rápidas para continuar sua jornada.",["Preciso ter cartão de crédito?","Como funciona o acesso?","O curso serve para iniciantes?","Onde pedir suporte?"]]}; const [title, desc, items] = content[screen]; return <div className="mx-auto max-w-3xl"><div className="rounded-3xl bg-[#101827] p-8 text-white"><p className="text-sm font-bold text-[#fca311]">DOMINE SUAS MILHAS</p><h2 className="mt-3 text-3xl font-black">{title}</h2><p className="mt-4 max-w-xl leading-7 text-slate-300">{desc}</p></div><div className="mt-5 grid gap-3">{items.map((item:string,i:number)=><details key={item} className="group rounded-2xl border border-[#e5e5e5] bg-white p-5"><summary className="flex cursor-pointer list-none items-center gap-4 font-black"><span className="grid size-9 place-items-center rounded-full bg-[#fff2d8] text-[#c37800]">{i+1}</span>{item}<ChevronDown className="ml-auto transition group-open:rotate-180" size={18}/></summary><p className="mt-4 text-sm leading-6 text-slate-500">Conteúdo demonstrativo do MVP. Aqui entra a explicação detalhada e o próximo passo recomendado.</p></details>)}</div></div> }
export default function Page() { const [screen, setScreen] = useState("cover"); const [language, setLanguage] = useState("PT-BR"); const content = screen === "cover" ? <Cover setScreen={setScreen} /> : screen === "concept" ? <Concept setScreen={setScreen} /> : screen === "access" ? <Access /> : <Generic screen={screen} setScreen={setScreen} language={language} />; return <AppShell screen={screen} setScreen={setScreen} language={language} setLanguage={setLanguage}>{content}</AppShell> }
